'use strict';
const path = require('path');
const root = path.resolve(process.argv[2]);
process.chdir(root);
require(path.join(root, 'node_modules/@babel/register'))({ extensions: ['.ts'], cwd: root, cache: false });
const { parse } = require(path.join(root, 'src/language/parser'));
const { buildSchema } = require(path.join(root, 'src/utilities/buildASTSchema'));
const { validate } = require(path.join(root, 'src/validation/validate'));
const { OverlappingFieldsCanBeMergedRule } = require(path.join(root, 'src/validation/rules/OverlappingFieldsCanBeMergedRule'));

const schema = buildSchema(`
  input In { a: Int, b: Int }
  type Query {
    a: Int
    f(a: Int, b: Int, x1: Int, x2: Int, in: In, s: String, a90071992547409920: Int, a90071992547409921: Int, a01: Int, a1: Int, a001: Int): Int
  }
`);
function check(label, q) {
  const errs = validate(schema, parse(q), [OverlappingFieldsCanBeMergedRule]);
  console.log(label.padEnd(34), errs.length ? errs.map(e => e.message).join(' | ') : 'OK');
}
check('reordered args', '{ f(a: 1, b: 2) f(b: 2, a: 1) }');
check('bigint names reordered', '{ f(a90071992547409920: 1, a90071992547409921: 2) f(a90071992547409921: 2, a90071992547409920: 1) }');
check('leading zeros reordered', '{ f(a01: 1, a1: 2, a001: 3) f(a001: 3, a1: 2, a01: 1) }');
check('dup same', '{ f(a: 1, a: 2) f(a: 1, a: 2) }');
check('dup vs other', '{ f(a: 1, a: 1) f(a: 1, b: 1) }');
check('dup swapped', '{ f(a: 1, a: 2) f(a: 2, a: 1) }');
check('block vs plain string', '{ f(s: "x") f(s: """x""") }');
check('string injection', '{ f(s: "x\\", a: \\"1") f(s: "x", a: 1) }');
check('no args vs empty', '{ f f }');
check('var', 'query($v: Int){ f(a: $v) f(a: $v) }');
check('nested obj reorder', '{ f(in: {a: 1, b: 2}) f(in: {b: 2, a: 1}) }');
check('differ', '{ f(a: 1) f(a: 2) }');
check('differ count', '{ f(a: 1) f(a: 1, b: 2) }');

for (const n of [500, 1000, 2000, 4000]) {
  const q = parse('{ ' + 'a '.repeat(n) + '}');
  const t = process.hrtime.bigint();
  const errs = validate(schema, q, [OverlappingFieldsCanBeMergedRule]);
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  console.log(`repeated no-arg field x${n}: ${ms.toFixed(0)} ms, errors=${errs.length}`);
}
for (const n of [500, 1000, 2000]) {
  const q = parse('{ ' + 'f(a: 1, b: 2, in: {a: 1, b: 2}) '.repeat(n) + '}');
  const t = process.hrtime.bigint();
  const errs = validate(schema, q, [OverlappingFieldsCanBeMergedRule]);
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  console.log(`repeated 3-arg field x${n}: ${ms.toFixed(0)} ms, errors=${errs.length}`);
}
EOF
