'use strict';
const path = require('path');
const root = path.resolve(process.argv[2]);
process.chdir(root);
require(path.join(root, 'node_modules/@babel/register'))({ extensions: ['.ts'], cwd: root, cache: false });
const { parse } = require(path.join(root, 'src/language/parser'));
const { buildSchema } = require(path.join(root, 'src/utilities/buildASTSchema'));
const { validate } = require(path.join(root, 'src/validation/validate'));
const { specifiedRules } = require(path.join(root, 'src/validation/specifiedRules'));
const schema = buildSchema(`type Query { a: Int  node: Node } type Node { id: ID name: String node: Node }`);
function time(label, src, rules) {
  const q = parse(src);
  let best = Infinity, errs;
  for (let i = 0; i < 3; i++) {
    const t = process.hrtime.bigint();
    errs = validate(schema, q, rules);
    best = Math.min(best, Number(process.hrtime.bigint() - t) / 1e6);
  }
  console.log(`${label}: ${best.toFixed(1)} ms (bytes=${src.length}, errors=${errs.length})`);
}
for (const n of [100, 1000, 2000]) time(`{a x${n}} all specifiedRules`, '{ ' + 'a '.repeat(n) + '}', specifiedRules);
// realistic: many fragments each selecting id/name on the same parent
for (const n of [50, 200]) {
  let src = '{ node { ' + Array.from({length: n}, (_, i) => `...F${i}`).join(' ') + ' } }\n';
  for (let i = 0; i < n; i++) src += `fragment F${i} on Node { id name }\n`;
  time(`${n} fragments selecting id,name`, src, specifiedRules);
}
EOF
